"""Guards A2A session contexts and enforces an active-context upper limit."""

from __future__ import annotations

import asyncio
from typing import Any

import structlog
from a2a.types import TaskState

from rasa.core.a2a_server.config import DEFAULT_MAX_A2A_CONTEXTS

structlogger = structlog.get_logger()

# Terminal outcomes that release a ``context_id`` from the active-session set.
RELEASE_CONTEXT_STATES = frozenset(
    {
        TaskState.completed,
        TaskState.canceled,
        TaskState.failed,
        TaskState.rejected,
    }
)

_USER_ID_METADATA_KEY = "user_id"


class ContextLimitExceeded(Exception):
    """Raised when a new ``context_id`` would exceed ``max_contexts``."""


def user_id_from_metadata(metadata: dict[str, Any]) -> str | None:
    """Extract orchestrator ``user_id`` from A2A request metadata."""
    value = metadata.get(_USER_ID_METADATA_KEY)
    if isinstance(value, str) and value.strip():
        return value.strip()
    return None


class A2AContextGuard:
    """Tracks active A2A sessions and enforces a ``max_contexts`` cap.

    A ``context_id`` counts toward the cap from the first ``message/send`` until
    a terminal task outcome (``completed``, ``canceled``, ``failed``, or
    ``rejected``) with no in-flight ``execute()`` for that context.
    ``input_required`` keeps the session reserved for follow-up messages.
    """

    def __init__(self, *, max_contexts: int | None = DEFAULT_MAX_A2A_CONTEXTS) -> None:
        if max_contexts == 0:
            max_contexts = None
        elif max_contexts is not None and max_contexts < 1:
            raise ValueError("max_contexts must be at least 1 when set.")
        self._max_contexts = max_contexts
        self._active_context_ids: set[str] = set()
        self._in_flight_by_context: dict[str, int] = {}
        self._user_id_to_contexts: dict[str, set[str]] = {}
        self._lock = asyncio.Lock()

    @property
    def max_contexts(self) -> int | None:
        return self._max_contexts

    @property
    def active_context_count(self) -> int:
        return len(self._active_context_ids)

    def get_active_context_ids(self) -> frozenset[str]:
        return frozenset(self._active_context_ids)

    async def begin_turn(
        self,
        context_id: str,
        *,
        metadata: dict[str, Any] | None = None,
    ) -> None:
        """Reserve ``context_id`` for an in-flight turn; enforce ``max_contexts``."""
        async with self._lock:
            is_new_context = context_id not in self._active_context_ids
            if (
                is_new_context
                and self._max_contexts is not None
                and len(self._active_context_ids) >= self._max_contexts
            ):
                raise ContextLimitExceeded(
                    f"Active A2A context limit ({self._max_contexts}) reached."
                )

            self._active_context_ids.add(context_id)
            self._in_flight_by_context[context_id] = (
                self._in_flight_by_context.get(context_id, 0) + 1
            )

            user_id = user_id_from_metadata(metadata or {})
            if user_id:
                contexts_for_user = self._user_id_to_contexts.setdefault(user_id, set())
                if len(contexts_for_user) >= 1 and context_id not in contexts_for_user:
                    structlogger.warning(
                        "a2a_server.context_guard.same_user_concurrent_contexts",
                        user_id=user_id,
                        context_id=context_id,
                        other_context_ids=sorted(contexts_for_user - {context_id}),
                    )
                contexts_for_user.add(context_id)

    async def end_turn(
        self,
        context_id: str,
        *,
        terminal_state: TaskState | None,
    ) -> None:
        """Decrement in-flight count and release the session on terminal outcomes."""
        async with self._lock:
            in_flight = self._in_flight_by_context.get(context_id, 0)
            if in_flight <= 1:
                self._in_flight_by_context.pop(context_id, None)
            else:
                self._in_flight_by_context[context_id] = in_flight - 1

            if (
                terminal_state in RELEASE_CONTEXT_STATES
                and context_id not in self._in_flight_by_context
            ):
                self._active_context_ids.discard(context_id)
                for user_id, contexts in list(self._user_id_to_contexts.items()):
                    contexts.discard(context_id)
                    if not contexts:
                        del self._user_id_to_contexts[user_id]

    async def clear(self) -> None:
        """Drop all tracked sessions (server shutdown)."""
        async with self._lock:
            self._active_context_ids.clear()
            self._in_flight_by_context.clear()
            self._user_id_to_contexts.clear()
